import{_ as t,c as a,o as r,ag as o}from"./chunks/framework.CQuhCYrb.js";const c=JSON.parse('{"title":"Airborne Equipment Rigging","description":"","frontmatter":{"title":"Airborne Equipment Rigging"},"headers":[],"relativePath":"ai-ml/airborne-equipment-rigging.md","filePath":"ai-ml/airborne-equipment-rigging.md","lastUpdated":null}'),n={name:"ai-ml/airborne-equipment-rigging.md"};function s(h,e,i,l,d,u){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="airborne-equipment-rigging" tabindex="-1">Airborne Equipment Rigging <a class="header-anchor" href="#airborne-equipment-rigging" aria-label="Permalink to &quot;Airborne Equipment Rigging&quot;">​</a></h1><h2 id="step-by-step-rigex-guide" tabindex="-1">Step-by-Step RIGEX Guide <a class="header-anchor" href="#step-by-step-rigex-guide" aria-label="Permalink to &quot;Step-by-Step RIGEX Guide&quot;">​</a></h2><p>This is a draft page used to outline and refine the steps for RIGEX preparation. Once finalized, this page will be marked as official. For the full standards, refer to the document: <em>[Standards.pdf]</em>.</p><h3 id="nomenclature" tabindex="-1">Nomenclature <a class="header-anchor" href="#nomenclature" aria-label="Permalink to &quot;Nomenclature&quot;">​</a></h3><p>To study Jumpmaster nomenclature, see the following resources:</p><ul><li><p><a href="https://u.pcloud.link/publink/show?code=kZi5Qc0ZyXlbkmv6MkF03azt0U28AzpeRAv7%7C" target="_blank" rel="noreferrer">Flashcards with JumpMaster Nomenclature (Latest Update)</a></p></li><li><p><a href="#">Master MC 6 Nomenclature Flashcards.pdf</a></p></li><li><p><em>[ MC-6 Nomenclature]</em></p></li></ul><h3 id="harness-single-point-release-and-molle-setup" tabindex="-1">Harness Single Point Release and MOLLE Setup <a class="header-anchor" href="#harness-single-point-release-and-molle-setup" aria-label="Permalink to &quot;Harness Single Point Release and MOLLE Setup&quot;">​</a></h3><ol><li><strong>Turn Over the Adjustable Cross Strap:</strong></li></ol><h3 id="flip-the-adjustable-cross-strap-on-the-harness-single-point-release-hspr-to-access-the-d-ring-attachment-points" tabindex="-1">Flip the <strong>adjustable cross strap</strong> on the <strong>Harness Single Point Release (HSPR)</strong> to access the D-ring attachment points. <a class="header-anchor" href="#flip-the-adjustable-cross-strap-on-the-harness-single-point-release-hspr-to-access-the-d-ring-attachment-points" aria-label="Permalink to &quot;Flip the **adjustable cross strap** on the **Harness Single Point Release (HSPR)** to access the D-ring attachment points.&quot;">​</a></h3><h3 id="pass-the-release-handle-cable-through-the-release-handle-cross-strap-and-secure-it-using-hook-pile-tape" tabindex="-1">Pass the <strong>release handle cable</strong> through the release handle cross strap and secure it using hook pile tape. <a class="header-anchor" href="#pass-the-release-handle-cable-through-the-release-handle-cross-strap-and-secure-it-using-hook-pile-tape" aria-label="Permalink to &quot;Pass the **release handle cable** through the release handle cross strap and secure it using hook pile tape.&quot;">​</a></h3><ol><li><strong>Attach the Triangle Links:</strong></li></ol><h3 id="feed-the-triangle-links-through-the-white-attaching-loop-on-the-harness-ensuring-that-the-snap-hooks-face-downward" tabindex="-1">Feed the <strong>triangle links</strong> through the <strong>white attaching loop</strong> on the harness, ensuring that the snap hooks face downward. <a class="header-anchor" href="#feed-the-triangle-links-through-the-white-attaching-loop-on-the-harness-ensuring-that-the-snap-hooks-face-downward" aria-label="Permalink to &quot;Feed the **triangle links** through the **white attaching loop** on the harness, ensuring that the snap hooks face downward.&quot;">​</a></h3><h3 id="thread-the-green-attaching-loop-through-the-white-attaching-loop-and-secure-it" tabindex="-1">Thread the <strong>green attaching loop</strong> through the white attaching loop and secure it. <a class="header-anchor" href="#thread-the-green-attaching-loop-through-the-white-attaching-loop-and-secure-it" aria-label="Permalink to &quot;Thread the **green attaching loop** through the white attaching loop and secure it.&quot;">​</a></h3><h3 id="pass-the-red-attaching-loop-through-the-grommet-on-the-cross-strap-ensuring-it-is-aligned-correctly" tabindex="-1">Pass the <strong>red attaching loop</strong> through the grommet on the cross strap, ensuring it is aligned correctly. <a class="header-anchor" href="#pass-the-red-attaching-loop-through-the-grommet-on-the-cross-strap-ensuring-it-is-aligned-correctly" aria-label="Permalink to &quot;Pass the **red attaching loop** through the grommet on the cross strap, ensuring it is aligned correctly.&quot;">​</a></h3><ol><li><strong>Route the Release Handle Cable:</strong></li></ol><h3 id="run-the-release-handle-cable-through-the-red-attaching-loop-for-additional-security" tabindex="-1">Run the <strong>release handle cable</strong> through the <strong>red attaching loop</strong> for additional security. <a class="header-anchor" href="#run-the-release-handle-cable-through-the-red-attaching-loop-for-additional-security" aria-label="Permalink to &quot;Run the **release handle cable** through the **red attaching loop** for additional security.&quot;">​</a></h3><h3 id="guide-the-cable-through-the-webbing-retainer-and-the-cable-loop-retainer-to-keep-the-cable-organized-and-free-of-tangles" tabindex="-1">Guide the cable through the <strong>webbing retainer</strong> and the <strong>cable loop retainer</strong> to keep the cable organized and free of tangles. <a class="header-anchor" href="#guide-the-cable-through-the-webbing-retainer-and-the-cable-loop-retainer-to-keep-the-cable-organized-and-free-of-tangles" aria-label="Permalink to &quot;Guide the cable through the **webbing retainer** and the **cable loop retainer** to keep the cable organized and free of tangles.&quot;">​</a></h3><ol><li><strong>Prepare the Harness:</strong></li></ol><h3 id="lay-the-harness-down-with-all-components-facing-downward-ensuring-proper-layout-for-the-following-steps" tabindex="-1">Lay the harness down with all components facing downward, ensuring proper layout for the following steps. <a class="header-anchor" href="#lay-the-harness-down-with-all-components-facing-downward-ensuring-proper-layout-for-the-following-steps" aria-label="Permalink to &quot;Lay the harness down with all components facing downward, ensuring proper layout for the following steps.&quot;">​</a></h3><ol><li><strong>Position the MOLLE:</strong></li></ol><h3 id="place-the-molle-face-down-on-the-harness-with-the-adjustable-shoulder-straps-facing-upwards-the-e-tool-or-canteen-pouch-should-fit-within-the-cross-strap-of-the-molle" tabindex="-1">Place the <strong>MOLLE</strong> face down on the harness, with the adjustable shoulder straps facing upwards. The <strong>E-tool</strong> or <strong>canteen pouch</strong> should fit within the cross strap of the MOLLE. <a class="header-anchor" href="#place-the-molle-face-down-on-the-harness-with-the-adjustable-shoulder-straps-facing-upwards-the-e-tool-or-canteen-pouch-should-fit-within-the-cross-strap-of-the-molle" aria-label="Permalink to &quot;Place the **MOLLE** face down on the harness, with the adjustable shoulder straps facing upwards. The **E-tool** or **canteen pouch** should fit within the cross strap of the MOLLE.&quot;">​</a></h3><ol><li><strong>Attach the Equipment Retainer Strap:</strong></li></ol><h3 id="run-the-equipment-retainer-strap-through-the-shoulder-holes-of-the-molle-ensuring-it-runs-on-the-outside-of-the-shoulder-straps" tabindex="-1">Run the <strong>equipment retainer strap</strong> through the shoulder holes of the MOLLE, ensuring it runs on the outside of the shoulder straps. <a class="header-anchor" href="#run-the-equipment-retainer-strap-through-the-shoulder-holes-of-the-molle-ensuring-it-runs-on-the-outside-of-the-shoulder-straps" aria-label="Permalink to &quot;Run the **equipment retainer strap** through the shoulder holes of the MOLLE, ensuring it runs on the outside of the shoulder straps.&quot;">​</a></h3><h3 id="the-straps-should-be-routed-diagonally-towards-the-bottom-of-the-molle-below-the-shoulder-straps" tabindex="-1">The straps should be routed diagonally towards the bottom of the MOLLE, below the shoulder straps. <a class="header-anchor" href="#the-straps-should-be-routed-diagonally-towards-the-bottom-of-the-molle-below-the-shoulder-straps" aria-label="Permalink to &quot;The straps should be routed diagonally towards the bottom of the MOLLE, below the shoulder straps.&quot;">​</a></h3><h3 id="feed-the-friction-adapter-through-the-bottom-of-the-molle-below-the-plastic-frame-running-it-towards-the-shoulder-straps" tabindex="-1">Feed the <strong>friction adapter</strong> through the bottom of the MOLLE, below the plastic frame, running it towards the shoulder straps. <a class="header-anchor" href="#feed-the-friction-adapter-through-the-bottom-of-the-molle-below-the-plastic-frame-running-it-towards-the-shoulder-straps" aria-label="Permalink to &quot;Feed the **friction adapter** through the bottom of the MOLLE, below the plastic frame, running it towards the shoulder straps.&quot;">​</a></h3><h3 id="connect-the-equipment-retainer-strap-to-the-opposite-side-friction-adapter-secure-and-tighten-it-with-a-quick-release-pulling-the-assembly-upwards-towards-the-shoulder-straps" tabindex="-1">Connect the equipment retainer strap to the opposite-side friction adapter. Secure and tighten it with a quick release, pulling the assembly upwards towards the shoulder straps. <a class="header-anchor" href="#connect-the-equipment-retainer-strap-to-the-opposite-side-friction-adapter-secure-and-tighten-it-with-a-quick-release-pulling-the-assembly-upwards-towards-the-shoulder-straps" aria-label="Permalink to &quot;Connect the equipment retainer strap to the opposite-side friction adapter. Secure and tighten it with a quick release, pulling the assembly upwards towards the shoulder straps.&quot;">​</a></h3><ol><li><p><strong>Manage Excess Straps:</strong></p></li><li><p><strong>S-roll</strong> any excess straps, ensuring no more than three fingers&#39; worth of excess remains. Secure the rolled-up straps with rubber bands to prevent them from hanging loosely.</p></li><li><p><strong>Attach the Lowering Line:</strong></p></li></ol><h3 id="take-the-looped-end-hook-pile-tape-lowering-line-and-run-it-from-the-shoulder-area-down-towards-the-bottom-of-the-molle" tabindex="-1">Take the <strong>looped end hook pile tape lowering line</strong> and run it from the shoulder area down towards the bottom of the MOLLE. <a class="header-anchor" href="#take-the-looped-end-hook-pile-tape-lowering-line-and-run-it-from-the-shoulder-area-down-towards-the-bottom-of-the-molle" aria-label="Permalink to &quot;Take the **looped end hook pile tape lowering line** and run it from the shoulder area down towards the bottom of the MOLLE.&quot;">​</a></h3><h3 id="ensure-the-lowering-line-passes-under-the-molle-and-loops-back-onto-itself-pulling-it-up-at-the-intersection-of-the-equipment-retainer-straps-for-secure-attachment" tabindex="-1">Ensure the lowering line passes under the MOLLE and loops back onto itself, pulling it up at the intersection of the equipment retainer straps for secure attachment. <a class="header-anchor" href="#ensure-the-lowering-line-passes-under-the-molle-and-loops-back-onto-itself-pulling-it-up-at-the-intersection-of-the-equipment-retainer-straps-for-secure-attachment" aria-label="Permalink to &quot;Ensure the lowering line passes under the MOLLE and loops back onto itself, pulling it up at the intersection of the equipment retainer straps for secure attachment.&quot;">​</a></h3><h3 id="steps-for-mawc-modular-airborne-weapons-case-rigging" tabindex="-1">Steps for MAWC (Modular Airborne Weapons Case) Rigging <a class="header-anchor" href="#steps-for-mawc-modular-airborne-weapons-case-rigging" aria-label="Permalink to &quot;Steps for MAWC (Modular Airborne Weapons Case) Rigging&quot;">​</a></h3><ol><li><strong>Nose Cone Adjustment:</strong></li></ol><h3 id="ensure-the-adjustable-nose-cone-is-sized-correctly-for-an-m4-dummy-rifle-with-the-butt-stock-fully-collapsed" tabindex="-1">Ensure the <strong>adjustable nose cone</strong> is sized correctly for an M4 dummy rifle with the butt stock fully collapsed. <a class="header-anchor" href="#ensure-the-adjustable-nose-cone-is-sized-correctly-for-an-m4-dummy-rifle-with-the-butt-stock-fully-collapsed" aria-label="Permalink to &quot;Ensure the **adjustable nose cone** is sized correctly for an M4 dummy rifle with the butt stock fully collapsed.&quot;">​</a></h3><h3 id="tighten-the-nose-cone-securing-straps-around-the-rifle-to-prevent-movement" tabindex="-1">Tighten the <strong>nose cone securing straps</strong> around the rifle to prevent movement. <a class="header-anchor" href="#tighten-the-nose-cone-securing-straps-around-the-rifle-to-prevent-movement" aria-label="Permalink to &quot;Tighten the **nose cone securing straps** around the rifle to prevent movement.&quot;">​</a></h3><ol><li><strong>Snap Shackle Preparation:</strong></li></ol><h3 id="adjust-the-snap-shackle-to-the-4th-rung-of-the-pouch-attachment-ladder-system-pals-on-the-mawc" tabindex="-1">Adjust the <strong>snap shackle</strong> to the 4th rung of the <strong>Pouch Attachment Ladder System (PALS)</strong> on the MAWC. <a class="header-anchor" href="#adjust-the-snap-shackle-to-the-4th-rung-of-the-pouch-attachment-ladder-system-pals-on-the-mawc" aria-label="Permalink to &quot;Adjust the **snap shackle** to the 4th rung of the **Pouch Attachment Ladder System (PALS)** on the MAWC.&quot;">​</a></h3><h3 id="ensure-the-snap-shackle-s-locking-pin-is-securely-engaged-and-the-yellow-safety-lanyard-is-correctly-attached-and-stowed-in-the-pals-webbing" tabindex="-1">Ensure the snap shackle&#39;s <strong>locking pin</strong> is securely engaged, and the <strong>yellow safety lanyard</strong> is correctly attached and stowed in the PALS webbing. <a class="header-anchor" href="#ensure-the-snap-shackle-s-locking-pin-is-securely-engaged-and-the-yellow-safety-lanyard-is-correctly-attached-and-stowed-in-the-pals-webbing" aria-label="Permalink to &quot;Ensure the snap shackle&#39;s **locking pin** is securely engaged, and the **yellow safety lanyard** is correctly attached and stowed in the PALS webbing.&quot;">​</a></h3><ol><li><strong>Compression Straps:</strong></li></ol><h3 id="fully-extend-the-compression-straps-and-quick-release-buckles-on-the-mawc" tabindex="-1">Fully extend the <strong>compression straps</strong> and quick-release buckles on the MAWC. <a class="header-anchor" href="#fully-extend-the-compression-straps-and-quick-release-buckles-on-the-mawc" aria-label="Permalink to &quot;Fully extend the **compression straps** and quick-release buckles on the MAWC.&quot;">​</a></h3><h3 id="after-positioning-the-weapon-tighten-the-compression-straps-ensuring-that-the-excess-webbing-is-secured-with-the-webbing-retainers" tabindex="-1">After positioning the weapon, tighten the compression straps, ensuring that the excess webbing is secured with the webbing retainers. <a class="header-anchor" href="#after-positioning-the-weapon-tighten-the-compression-straps-ensuring-that-the-excess-webbing-is-secured-with-the-webbing-retainers" aria-label="Permalink to &quot;After positioning the weapon, tighten the compression straps, ensuring that the excess webbing is secured with the webbing retainers.&quot;">​</a></h3><ol><li><strong>Slide Fastener and Tabbed Thong:</strong></li></ol><h3 id="zip-up-the-slide-fastener-and-close-the-tabbed-thong-ensuring-the-slide-fastener-is-secured-to-the-first-rivet-pin-but-not-so-far-as-to-engage-the-spring-mechanism" tabindex="-1">Zip up the <strong>slide fastener</strong> and close the <strong>tabbed thong</strong>, ensuring the slide fastener is secured to the first rivet pin, but not so far as to engage the spring mechanism. <a class="header-anchor" href="#zip-up-the-slide-fastener-and-close-the-tabbed-thong-ensuring-the-slide-fastener-is-secured-to-the-first-rivet-pin-but-not-so-far-as-to-engage-the-spring-mechanism" aria-label="Permalink to &quot;Zip up the **slide fastener** and close the **tabbed thong**, ensuring the slide fastener is secured to the first rivet pin, but not so far as to engage the spring mechanism.&quot;">​</a></h3><h3 id="ensure-the-snap-fastener-is-correctly-closed" tabindex="-1">Ensure the <strong>snap fastener</strong> is correctly closed. <a class="header-anchor" href="#ensure-the-snap-fastener-is-correctly-closed" aria-label="Permalink to &quot;Ensure the **snap fastener** is correctly closed.&quot;">​</a></h3><ol><li><strong>Upper Tie-Down Tape:</strong></li></ol><h3 id="route-the-upper-tie-down-tape-through-the-opening-on-the-tabbed-thong-securing-it-with-a-single-or-double-looped-bow-knot-on-the-lead-edge-of-the-mawc" tabindex="-1">Route the <strong>upper tie-down tape</strong> through the opening on the tabbed thong, securing it with a single or double-looped bow knot on the lead edge of the MAWC. <a class="header-anchor" href="#route-the-upper-tie-down-tape-through-the-opening-on-the-tabbed-thong-securing-it-with-a-single-or-double-looped-bow-knot-on-the-lead-edge-of-the-mawc" aria-label="Permalink to &quot;Route the **upper tie-down tape** through the opening on the tabbed thong, securing it with a single or double-looped bow knot on the lead edge of the MAWC.&quot;">​</a></h3><ol><li><strong>Final Adjustments:</strong></li></ol><h3 id="confirm-that-the-weapon-is-properly-oriented-all-adjustable-buckles-are-secured-and-the-compression-straps-are-tight-ensure-the-snap-shackle-and-all-fasteners-are-engaged" tabindex="-1">Confirm that the weapon is properly oriented, all adjustable buckles are secured, and the compression straps are tight. Ensure the snap shackle and all fasteners are engaged. <a class="header-anchor" href="#confirm-that-the-weapon-is-properly-oriented-all-adjustable-buckles-are-secured-and-the-compression-straps-are-tight-ensure-the-snap-shackle-and-all-fasteners-are-engaged" aria-label="Permalink to &quot;Confirm that the weapon is properly oriented, all adjustable buckles are secured, and the compression straps are tight. Ensure the snap shackle and all fasteners are engaged.&quot;">​</a></h3><p>[Required]</p>',47)])])}const g=t(n,[["render",s]]);export{c as __pageData,g as default};
